  ensures merged(a1, a2, b, start, end)
{
  assert forall xs : seq<int> :: xs[0..|xs|] == xs;
  assert forall xs : seq<int>, a,b : int :: 0 <= a < b < |xs| ==> xs[a..b+1] == xs[a..b] + [xs[b]];
  var a1Pos := 0;
  var a2Pos := 0;
